class Solution {
public:
    int countAnagrams(std::string s) {
        long long MOD = 1e9 + 7;
        int n = s.size();
        std::vector<long long> fact(n + 1, 1), inv(n + 1, 1);
        auto modpow = [&](long long base, long long exp) {
            long long res = 1;
            base %= MOD;
            while (exp > 0) {
                if (exp % 2 == 1) res = (res * base) % MOD;
                base = (base * base) % MOD;
                exp /= 2;
            }
            return res;
        };
        for (int i = 1; i <= n; ++i) fact[i] = (fact[i - 1] * i) % MOD;
        inv[n] = modpow(fact[n], MOD - 2);
        for (int i = n - 1; i >= 0; --i) inv[i] = (inv[i + 1] * (i + 1)) % MOD;

        std::stringstream ss(s);
        std::string word;
        long long ans = 1;
        while (ss >> word) {
            int len = word.size();
            std::vector<int> count(26, 0);
            for (char c : word) count[c - 'a']++;
            long long ways = fact[len];
            for (int c : count) {
                if (c > 1) ways = (ways * inv[c]) % MOD;
            }
            ans = (ans * ways) % MOD;
        }
        return ans;
    }
};

class Solution {
    public int countAnagrams(String s) {
        long MOD = 1_000_000_007L;
        int n = s.length();
        long[] fact = new long[n + 1];
        long[] inv = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) fact[i] = (fact[i - 1] * i) % MOD;
        inv[n] = modPow(fact[n], MOD - 2, MOD);
        for (int i = n - 1; i >= 0; i--) inv[i] = (inv[i + 1] * (i + 1)) % MOD;

        String[] words = s.split(" ");
        long ans = 1;
        for (String w : words) {
            int[] count = new int[26];
            for (int i = 0; i < w.length(); i++) count[w.charAt(i) - 'a']++;
            long ways = fact[w.length()];
            for (int c : count) {
                if (c > 1) ways = (ways * inv[c]) % MOD;
            }
            ans = (ans * ways) % MOD;
        }
        return (int)ans;
    }
    private long modPow(long base, long exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }
}

var countAnagrams = function(s) {
    const MOD = 1000000007n;
    const n = s.length;
    const fact = new Array(n + 1);
    fact[0] = 1n;
    for (let i = 1; i <= n; i++) fact[i] = (fact[i - 1] * BigInt(i)) % MOD;

    const modPow = (base, exp) => {
        let res = 1n;
        base %= MOD;
        while (exp > 0n) {
            if (exp % 2n === 1n) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2n;
        }
        return res;
    };

    const inv = new Array(n + 1);
    inv[n] = modPow(fact[n], MOD - 2n);
    for (let i = n - 1; i >= 0; i--) inv[i] = (inv[i + 1] * BigInt(i + 1)) % MOD;

    const words = s.split(' ');
    let ans = 1n;
    for (const w of words) {
        const counts = {};
        for (const ch of w) counts[ch] = (counts[ch] || 0) + 1;
        let ways = fact[w.length];
        for (const ch in counts) {
            const c = counts[ch];
            if (c > 1) ways = (ways * inv[c]) % MOD;
        }
        ans = (ans * ways) % MOD;
    }
    return Number(ans);
};
